  const water = (y, col) => { let s = '<rect x="0" y="' + y + '" width="400" height="' + (260 - y) + '" fill="' + col + '"/>'; for (let i = 0; i < 6; i++) s += '<path class="wav" style="animation-delay:-' + i * .5 + 's" d="M' + (20 + i * 64) + ' ' + (y + 10 + (i % 3) * 12) + 'q8-4 16 0t16 0" stroke="#fff" stroke-width="1.5" fill="none" opacity=".5"/>'; return s; };
